(7547424, 1208650, 94815, '<td valign="top">No title required. So homey in an impressionistic, down-to-earth (and of course, understated) way.</td>', 'No title required. So homey in an impressionistic, down-to-earth (and of course, understated) way.', '2017-12-05 23:21:49.000000', NULL, 1),
